WITH base AS (SELECT *, LENGTH(plan) plan_length FROM subscriptions WHERE monthly_fee IS NULL), enriched AS (SELECT id, plan, status, LAG(plan_length) OVER (PARTITION BY customer_id ORDER BY end_date, id) prev_plan_length, LAG(monthly_fee) OVER (PARTITION BY customer_id ORDER BY end_date, id) prev_monthly_fee, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY end_date, id) row_seq, LAST_VALUE(monthly_fee) IGNORE NULLS OVER (ORDER BY monthly_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) last_known_monthly_fee FROM base WHERE plan_length BETWEEN 50 AND 78), metrics AS (SELECT id, prev_monthly_fee, AVG(prev_plan_length) OVER w_recent prev_plan_length_avg_3, RANK() OVER w_grp prev_plan_length_rank, ROW_NUMBER() OVER (PARTITION BY plan, status ORDER BY row_seq, id) row_seq_2, LEAD(last_known_monthly_fee, 1) OVER (PARTITION BY status ORDER BY row_seq, id) next_last_known_monthly_fee FROM enriched WINDOW w_recent AS (PARTITION BY status ORDER BY last_known_monthly_fee, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), w_grp AS (PARTITION BY plan ORDER BY prev_plan_length DESC NULLS FIRST)), enriched_subscriptions AS (SELECT id, prev_monthly_fee, prev_plan_length_rank, row_seq_2, AVG(next_last_known_monthly_fee) OVER (ORDER BY prev_plan_length_avg_3, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) next_last_known_monthly_fee_avg_2, SUM(prev_plan_length_rank) OVER (ORDER BY row_seq_2, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_prev_plan_length_rank FROM metrics), enriched_subscriptions_2 AS (SELECT *, MIN(prev_monthly_fee) OVER (ORDER BY prev_plan_length_rank, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) last4_min_prev_monthly_fee, COUNT(prev_monthly_fee) OVER (ORDER BY prev_plan_length_rank, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) last4_count_prev_monthly_fee, MAX(prev_monthly_fee) OVER (ORDER BY prev_plan_length_rank, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) last4_max_prev_monthly_fee, SUM(prev_plan_length_rank) OVER (ORDER BY running_prev_plan_length_rank, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_prev_plan_length_rank_2 FROM enriched_subscriptions) SELECT id, next_last_known_monthly_fee_avg_2, running_prev_plan_length_rank, last4_min_prev_monthly_fee, running_prev_plan_length_rank_2, LAG(prev_plan_length_rank, 1, 0) OVER (ORDER BY last4_max_prev_monthly_fee, id) prev_prev_plan_length_rank, LAG(prev_monthly_fee, 1) OVER (ORDER BY row_seq_2, id) prev_prev_monthly_fee FROM enriched_subscriptions_2
